entries[382321] = { ["name"] = "Ol' Smoky", ["text"] = "5 sec cast 3\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nObsidian Seared Alloy (4), Everburning Blasting Powder (8), Arclight Capacitor (2), Reinforced Machine Chassis , Spark (#247) (2)\nOptional Reagents:\nInfuse with Power (#111) , Customize Secondary Stats (#125) , Illustrious Insight (#93) , Add Embellishment (#226) , Spare Parts (#230)\nDrop:\nAssault of the Zaqali\nZone:\nAberrus, the Shadowed Crucible\nRecipe:\nPurchasable on the Auction House\n\nOl' Smoky\nBinds when picked up\nRanged Gun\n406 - 754 Damage Speed 3.00\n(193.3 damage per second)\n+257 Agility\n+416 Stamina\n+ 239 Random Stat 1\n+ 239 Random Stat 2\nDurability 120 / 120\n58" }
entries[382322] = { ["name"] = "Primal Deconstruction Charge", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire , Handful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nPrimal Deconstruction Charge\n\nUse: Inflicts 531 Fire damage to enemies in a 8 yard radius. This explosion is powerful enough to cause moderate siege damage.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382323] = { ["name"] = "Grease Grenade", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Handful of Serevite Bolts (4), Everburning Blasting Powder (6)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\nGrease Grenade\n\nUse: Launch a concealed grenade toward the target location, dealing 837 Nature damage and coating the ground in a sticky substance for 4 sec that slows enemy units within by 75%. (5 Min Cooldown)\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382324] = { ["name"] = "Tinker: Breath of Neltharion", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire (3), Handful of Serevite Bolts (5), Everburning Blasting Powder (8), Greased-Up Gears (4), Reinforced Machine Chassis\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nMeticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nTreasure:\nCrumpled Schematic\nZone:\nNeltharus\n\nTinker: Breath of Neltharion\nTinker Module\nUnique-Equipped: Breath of Neltharion (1)\nReveal a flamethrower to deal ( 517 * 13) Fire damage in a cone in front of you for 6 sec.\n58\n\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\"" }
entries[382325] = { ["name"] = "Projectile Propulsion Pinion", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrameless Lens , Greased-Up Gears (3), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nGather:\nDjaradin Cache\nZone:\nThe Waking Shores\n\nProjectile Propulsion Pinion\n\nUse: Permanently enchants a ranged weapon to grant 131 split between your highest and lowest secondary stats after you stand still for 3 sec.\n61" }
entries[382326] = { ["name"] = "High Intensity Thermal Scanner", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrameless Lens , Greased-Up Gears (3), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nFunction Over Form - Utility (20)\n\nHigh Intensity Thermal Scanner\n\nUse: Permanently enchants a ranged weapon to sometimes increase a secondary stat by 370 based upon the type of creature you are attacking.\n61" }
entries[382327] = { ["name"] = "Bundle of Fireworks", ["text"] = "1.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire (3), Stonecrust Hide , Everburning Blasting Powder (2)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\nBinds when picked up\n\"Contains an assortment of fireworks across many eras and from many cultures.\"\n<Right Click to Open>" }
entries[382328] = { ["name"] = "S.A.V.I.O.R.", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Order , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Greased-Up Gears (2), Arclight Capacitor\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nMechanical Mind (40)\n\nS.A.V.I.O.R.\nBinds when picked up\n\nUse: Place a friendly mechanical construct on the ground nearby which will offer moral support as your companions fall around you. It will resurrect all party or raid members within a reasonable distance after combat has ended. Cast time is reduced by quality.\n\nDoes not work on players whose spirits have been released, are above level 70, or have angered the robot.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382329] = { ["name"] = "Khaz'gorite Fisherfriend", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nKhaz'gorite Ore (10), Greased-Up Gears (4), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nIllustrious Insight (#93) , Spare Parts (#230)\nDrop:\nImmaculate Sac of Swog Treasures\nVendor:\nThe Great Swog\nCost:\nGold Coin of the Isles\nRecipe:\nPurchasable on the Auction House\n\nKhaz'gorite Fisherfriend\nBinds when picked up\nFishing Tool\n+ 90 Perception\nEquip: +15 Dragon Isles Fishing Skill\nRequires Fishing\n(1)" }
entries[382330] = { ["name"] = "Creature Combustion Canister", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (4), Shock-Spring Coil , Everburning Blasting Powder (6)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nProfession Trainer:\nDragon Isles Engineering (25)\nCost:\n1\n\nCreature Combustion Canister\n\nUse: Throw the canister, exploding the nearest meaty corpse into chunks of meat. Only usable outdoors.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382331] = { ["name"] = "D.U.C.K.O.Y.", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nContoured Fowlfeather (6), Resilient Leather , Handful of Serevite Bolts , Everburning Blasting Powder (2)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nFishing:\nDraconic Recipe in a Bottle\nRecipe:\nPurchasable on the Auction House\n\nD.U.C.K.O.Y.\nBinds when picked up\n\nUse: Activate a robotic duckling that wanders around, annoying your enemies before self-destructing for 779 Fire damage split between all nearby enemies.\n\nDamage is increased for each enemy struck, up to 5 enemies.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382332] = { ["name"] = "Quack-E", ["text"] = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nContoured Fowlfeather (60), Quack-E Quack Modulator , Malygite (2), Handful of Serevite Bolts (4), Shock-Spring Coil , Greased-Up Gears (2), Reinforced Machine Chassis\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 21\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 21\nCost:\n200\n\nQuack-E\nBinds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\n1 to 80 ( 80)" }
entries[382333] = { ["name"] = "Sticky Warp Grenade", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Decay , Handful of Serevite Bolts (6), Shock-Spring Coil (2), Everburning Blasting Powder (3)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nSticky Warp Grenade\n\nUse: Throw at a location, attaching itself to the surface or a nearby enemy. Detonates after 3 sec, swapping your position with itself and any attached enemy.\n\nItem quality affects the distance this can be thrown. Only usable outdoors.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382334] = { ["name"] = "Tinker: Alarm-O-Turret", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Ire (2), Shock-Spring Coil (3), Greased-Up Gears (3), Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nMeticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nTinker: Alarm-O-Turret\nTinker Module\nUnique-Equipped: Alarm-O-Turret (1)\nPlace a hidden Alarm-O-Turret on a nearby targeted location. If an enemy player enters its detection radius, it will alert you of their presence and attempt to defend the area for 30 sec or until destroyed.\n58\n\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\"" }
entries[382335] = { ["name"] = "Green Fireflight", ["text"] = "1.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAdamant Scales , Everburning Blasting Powder (2)\nVendor:\nRabul\nZone:\nValdrakken\nCost:\n200\n\nUse: Shoot a set of fireworks honoring the Green Dragonflight." }
entries[382336] = { ["name"] = "H.E.L.P.", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Ire (3), Mark of Honor (15), Handful of Serevite Bolts (6), Everburning Blasting Powder (4), Reinforced Machine Chassis\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nH.E.L.P.\nBinds when picked up\nToy\nUse: Fires a signal flare to alert nearby allies of incoming danger.\n\nCan only be used in battlegrounds. Signal flares cannot be fired in a given area by the same faction more than once every 3 min. (2 Min Cooldown)\n\"Hey Everyone, Look Please!\"" }
entries[382337] = { ["name"] = "Portable Tinker's Workbench", ["text"] = "5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrameless Lens , Handful of Serevite Bolts (2), Shock-Spring Coil , Greased-Up Gears\nVendor:\nRabul\nZone:\nValdrakken\nCost:\n75\n\nPortable Tinker's Workbench\nUse: Place down a Portable Tinker's Workbench to enable nearby engineers to practice their trade for 5*2 min.\n\nIt probably will not explode. (5 Min Cooldown)" }
