entries[382341] = { ["name"] = "Khaz'gorite Delver's Helmet", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nOptional Reagents:\nIllustrious Insight (#93) , Spare Parts (#230)\nVendor:\nDothenos\nZone:\nValdrakken\nValdrakken Accord - Renown 19\nCost:\n400\n\nVendor:\nUnatos\nZone:\nValdrakken\nValdrakken Accord - Renown 19\nCost:\n400\n\nKhaz'gorite Delver's Helmet\nBinds when picked up\nUnique-Equipped: Head (1)Mining Accessory\n+ 36 Deftness\n+ 36 Perception\nEquip: +6 Dragon Isles Mining Skill" }
