entries[382343] = { ["name"] = "Gravitational Displacer", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nPotion of Gusts , Handful of Serevite Bolts (2), Shock-Spring Coil , Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 9\nCost:\n200\n\nGravitational Displacer\n\nUse: Throw the displacer and activate it after 2 sec, pulling all enemies within 10 yards to its location. Only usable outdoors.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382344] = { ["name"] = "Tinker: Grounded Circuitry", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (4), Greased-Up Gears (2), Arclight Capacitor (2), Reinforced Machine Chassis\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nVendor:\nDothenos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\nVendor:\nUnatos\nZone:\nValdrakken\nValdrakken Accord - Renown 11\nCost:\n50\n\nTinker: Grounded Circuitry\nTinker Module\nUnique-Equipped: Grounded Circuitry (1)\nGuarantees the next slotted Tinker use to succeed. The cooldown of this effect is reduced at higher qualities.\n58\n\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\"" }
entries[382345] = { ["name"] = "Assorted Safety Fuses", ["text"] = "1.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nWildercloth (3), Handful of Serevite Bolts (3), Shock-Spring Coil , Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nExplosives - EZ-Thro\n\n58\nCrafting Reagent\n\"A critical component when creating Engineering bombs intended for people with careless hands. Can be bought and sold on the auction house.\"" }
entries[382346] = { ["name"] = "Haphazardly Tethered Wires", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Earth (4), Handful of Serevite Bolts (3)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nProfession Trainer:\nDragon Isles Engineering (25)\nCost:\n1\n\nHaphazardly Tethered Wires\n58\nFinishing Crafting Reagent\n\nWhen crafting: You are 15% more likely to improve at Engineering, but Recipe Difficulty is increased by 30.\nUsable with: Most Dragon Isles Engineering recipes." }
entries[382347] = { ["name"] = "Witherbolt", ["text"] = "Instant\nInfused with decay magic from a nearby totem, Trickclaw Mystic fires a withering bolt, inflicting 14 Nature damage and applying Withering ." }
entries[382348] = { ["name"] = "Overcharged Overclocker", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRousing Fire (5), Handful of Serevite Bolts (2), Shock-Spring Coil (3)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nProfession Trainer:\nDragon Isles Engineering (40)\nCost:\n1\n50\n\nOvercharged Overclocker\n58\nFinishing Crafting Reagent\n\nWhen crafting: Increases your Resourcefulness by 55 and Ingenuity by 50.\nUsable with: Most Dragon Isles Engineering recipes." }
entries[382349] = { ["name"] = "Critical Failure Prevention Unit", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nShock-Spring Coil (3), Arclight Capacitor , Reinforced Machine Chassis , Primal Deconstruction Charge (2)\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nTinker Malfunction\nRequires:\nSpecialization: Function Over Form - Gears for Gear (20)\n\nCritical Failure Prevention Unit\n58\nOptional Crafting Reagent\n+20 Recipe Difficulty\nProvides the following property: Tinkers slotted into this device can no longer catastrophically malfunction.\nUsable with: Dragon Isles Engineering recipes for Epic goggles and bracers." }
entries[382350] = { ["name"] = "Calibrated Safety Switch", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nShock-Spring Coil (2), Greased-Up Gears , Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nTinker Malfunction\nRequires:\nSpecialization: Function Over Form - Gears for Gear (20)\n\nCalibrated Safety Switch\n58\nOptional Crafting Reagent\n+20 Recipe Difficulty\nProvides the following property: Reduces the likelihood of this device's tinker malfunctioning by 15%. Does not stack with similar specialization bonuses.\nUsable with: Dragon Isles Engineering recipes for Epic goggles and bracers." }
entries[382351] = { ["name"] = "Magazine of Healing Darts", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nRefreshing Healing Potion (10), Everburning Blasting Powder (3), Arclight Capacitor , Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nFunction Over Form - Gears for Gear (10)\n\nMagazine of Healing Darts\n58\nOptional Crafting Reagent\n+35 Recipe Difficulty\nProvides the following property: When you heal you sometimes fire a Healing Dart. Also add Unique-Equipped: Embellished (2).\nUsable with: Dragon Isles recipes for most unembellished Epic equipment." }
entries[382353] = { ["name"] = "I.W.I.N. Button Mk10", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts , Shock-Spring Coil , Arclight Capacitor , Primal Deconstruction Charge\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nSpecialization:\nExplosives (40)\n\nI.W.I.N. Button Mk10\nBinds when picked up\n\nUse: Press the button to call in an air strike at the designated location, dealing 5283 Fire damage to all enemies in the strike zone. Only usable outdoors.\n58\nRequires Dragon Isles Engineering\n(1)" }
entries[382354] = { ["name"] = "Suspiciously Ticking Crate", ["text"] = "2 sec cast 20 hrs cooldown\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire , Handful of Serevite Bolts (3), Shock-Spring Coil , Everburning Blasting Powder (10)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nExplosives - Short Fuse (30)\n\nSuspiciously Ticking Crate\nBinds when picked up\n58\n\"Contains an assortment of dangerous bombs.\"\n<Right Click to Open>" }
