entries[382358] = { ["name"] = "Suspiciously Silent Crate", ["text"] = "2 sec cast 20 hrs cooldown\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire , Handful of Serevite Bolts (3), Shock-Spring Coil , Everburning Blasting Powder (10), Assorted Safety Fuses (2)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nExplosives - EZ-Thro (30)\n\nSuspiciously Silent Crate\nBinds when picked up\n58\n\"Contains an assortment of Ez-Thro Bombs.\"\n<Right Click to Open>" }
entries[382359] = { ["name"] = "Tinker: Supercollide-O-Tron", ["text"] = "3.5 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Fire (5), Awakened Order (3), Shock-Spring Coil (3), Greased-Up Gears (10), Arclight Capacitor (3), Reinforced Machine Chassis\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nMeticulously crafted tinkers of a high quality have a much greater chance of succeeding.\nSpecialization:\nMechanical Mind - Inventions (40)\n\nTinker: Supercollide-O-Tron\nTinker Module\nUnique-Equipped: Supercollide-O-Tron (1)\nLock on to a distant enemy target, up to 12 to 60 yds away. After 1.5 sec, if your path remains unobstructed, you will charge toward them at the speed of sound. Both you and your target will be stunned for 1.5 sec upon collision.\n58\nRequires Dragon Isles Engineering\n(1)\n\"Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.\"" }
entries[382361] = { ["name"] = "Razor-Sharp Gear", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nQueen's Ruby , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\nRazor-Sharp Gear\n58\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Critical Strike.\nUsable with: Dragon Isles Engineering recipes for Epic goggles and bracers." }
entries[382362] = { ["name"] = "Rapidly Ticking Gear", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nVibrant Emerald , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\nRapidly Ticking Gear\n58\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Haste.\nUsable with: Dragon Isles Engineering recipes for Epic goggles and bracers." }
