entries[382364] = { ["name"] = "One-Size-Fits-All Gear", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nMystic Sapphire , Handful of Serevite Bolts (4), Greased-Up Gears\nOptional Reagents:\nSpare Parts (#230) , Lesser Illustrious Insight (#92)\nDiscovery:\nWhen crafting Greased-Up Gears\nRequires:\nSpecialization: Function Over Form - Gears for Gear\n\nOne-Size-Fits-All Gear\n58\nOptional Crafting Reagent\n+25 Recipe Difficulty\nProvides the following property: Allocate the secondary stats of Engineering crafted goggles or bracers to Versatility.\nUsable with: Dragon Isles Engineering recipes for Epic goggles and bracers." }
entries[382365] = { ["name"] = "Completely Safe Rockets", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (2), Everburning Blasting Powder (4)\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nFunction Over Form - Utility\n\nCompletely Safe Rockets\n\nUse: Throw in a seemingly endless supply of tiny rockets into your quiver. Your attacks have a chance to fire one of these rockets which explodes on impact to deal 1766 Fire damage in a small radius around the target.\n\nLasts 60 min.\n58" }
entries[382366] = { ["name"] = "Endless Stack of Needles", ["text"] = "2 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nHandful of Serevite Bolts (2), Shock-Spring Coil , Greased-Up Gears\nOptional Reagents:\nLesser Illustrious Insight (#92) , Spare Parts (#230)\nSpecialization:\nFunction Over Form - Utility (10)\n\nEndless Stack of Needles\n\nUse: Replace your traditional ammunition with sharp needles that cause your auto-attacks to also apply a bleed to the target which deals 424 Physical damage every 2 sec.\n\nLasts 60 min.\n58" }
entries[382367] = { ["name"] = "Wyrmhole Generator: Dragon Isles", ["text"] = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nAwakened Order (3), Handful of Serevite Bolts (2), Shock-Spring Coil , Greased-Up Gears (2), Arclight Capacitor (3), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind\n\nWyrmhole Generator: Dragon Isles\nBinds when used\nToy\nUse: Open a wormhole that allows the user to quickly travel to a random location in the Dragon Isles.\n\nEngineers that specialize into triangulation can learn to warp to specific locations. (30 Min Cooldown)\nRequires Dragon Isles Engineering\n(1)" }
entries[382368] = { ["name"] = "Centralized Precipitation Emitter", ["text"] = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFrosty Soul (3), Airy Soul (3), Elemental Harmony , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Arclight Capacitor (4), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind - Novelties (5)\n\nCentralized Precipitation Emitter\nBinds when used\nToy\nUse: Place down a Centralized Precipitation Emitter for up to 2 hrs that allows you to experience the fury of nature, by choice!\n\nA cloaking device attached to this machine ensures that only members of your party or raid can see the machine and its effects.\n\nCan only be used outside. (2 Hrs Cooldown)" }
entries[382369] = { ["name"] = "Environmental Emulator", ["text"] = "10 sec cast\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nFiery Soul (3), Earthen Soul (3), Elemental Harmony , Handful of Serevite Bolts (20), Shock-Spring Coil (3), Arclight Capacitor (4), Reinforced Machine Chassis\nSpecialization:\nMechanical Mind - Novelties (25)\n\nEnvironmental Emulator\nBinds when used\nToy\nUse: Place down an Environmental Emulator for up to 2 hrs that allows you to view the world from a different perspective.\n\nA cloaking device attached to this machine ensures that only members of your party or raid can see the machine and its effects.\n\nCan only be used outside. (2 Hrs Cooldown)" }
